<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use App\Models\{Property,User,Room,RoomType,Payment};
use App\Services\BookingService;
class HotelWorkflowTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void {parent::setUp();$this->seed();}
 private function owner():User{return User::where('role','owner')->firstOrFail();}
 private function data(Room $room,int $offset=10,int $duration=2):array{return ['room_id'=>$room->id,'guest_name'=>'Test Guest','guest_email'=>'guest@example.test','guests'=>2,'check_in'=>today()->addDays($offset)->toDateString(),'check_out'=>today()->addDays($offset+$duration)->toDateString()];}
 private function room():Room{return Room::whereHas('property',fn($q)=>$q->where('slug','the-aluna-ubud'))->firstOrFail();}
 public function test_staff_pages_require_authentication():void {$this->get('/app')->assertRedirect('/login');$this->post('/app/settings',[])->assertRedirect('/login');}
 public function test_all_staff_screens_render_for_owner():void {$this->actingAs($this->owner());foreach(['','/reservations','/calendar','/rooms','/guests','/housekeeping','/billing','/reports','/channels','/website','/mobile','/settings'] as $page)$this->get('/app'.$page)->assertOk();}
 public function test_marketplace_hotel_and_login_render():void {$this->get('/')->assertOk()->assertSee('The Aluna Ubud');$this->get('/hotels/the-aluna-ubud')->assertOk()->assertSee('Reserve your stay');$this->get('/login')->assertOk();}
 public function test_guest_can_book_with_server_calculated_price():void {$room=$this->room();$this->post('/hotels/the-aluna-ubud/book',$this->data($room)+['total'=>1])->assertRedirect();$this->assertDatabaseHas('reservations',['guest_email'=>'guest@example.test','total'=>1887000]);}
 public function test_overlapping_booking_is_rejected_but_adjacent_booking_is_allowed():void {$room=$this->room();$service=app(BookingService::class);$first=$service->create($room->property,$this->data($room));$adjacent=$service->create($room->property,$this->data($room,12));$this->assertNotSame($first->id,$adjacent->id);$this->expectException(ValidationException::class);$service->create($room->property,$this->data($room,11));}
 public function test_another_property_room_cannot_be_booked():void {$foreign=Property::where('slug','sora-house')->firstOrFail()->rooms()->firstOrFail();$this->post('/hotels/the-aluna-ubud/book',$this->data($foreign))->assertNotFound();}
 public function test_cancellation_releases_inventory():void {$room=$this->room();$service=app(BookingService::class);$r=$service->create($room->property,$this->data($room));$service->transition($r,'cancelled');$replacement=$service->create($room->property,$this->data($room));$this->assertNotSame($r->id,$replacement->id);}
 public function test_existing_reservation_keeps_original_rate():void {$room=$this->room();$r=app(BookingService::class)->create($room->property,$this->data($room));$original=$r->total;$room->type->update(['nightly_rate'=>1000000]);$this->assertSame($original,$r->fresh()->total);}
 public function test_checkin_requires_clean_room():void {$room=$this->room();$r=$room->reservations()->where('status','checked_in')->firstOrFail();$r->update(['status'=>'confirmed']);$room->update(['housekeeping_status'=>'dirty']);$this->actingAs($this->owner())->post('/app/reservations/'.$r->id.'/status',['status'=>'checked_in'])->assertSessionHasErrors('status');}
 public function test_checkout_requires_full_payment():void {$room=$this->room();$r=$room->reservations()->where('status','checked_in')->firstOrFail();$r->payments()->delete();$this->actingAs($this->owner())->post('/app/reservations/'.$r->id.'/status',['status'=>'checked_out'])->assertSessionHasErrors('status');$this->assertSame('checked_in',$r->fresh()->status);}
 public function test_payment_replay_does_not_duplicate_receipt():void {$room=$this->room();$r=app(BookingService::class)->create($room->property,$this->data($room));$this->actingAs($this->owner());$data=['amount'=>500000,'method'=>'cash','idempotency_key'=>(string)Str::uuid()];$this->post('/app/reservations/'.$r->id.'/payments',$data)->assertSessionHasNoErrors();$this->post('/app/reservations/'.$r->id.'/payments',$data)->assertSessionHasNoErrors();$this->assertSame(1,$r->payments()->count());}
 public function test_overpayment_is_rejected():void {$room=$this->room();$r=app(BookingService::class)->create($room->property,$this->data($room));$this->actingAs($this->owner())->post('/app/reservations/'.$r->id.'/payments',['amount'=>$r->total+1,'method'=>'cash','idempotency_key'=>(string)Str::uuid()])->assertSessionHasErrors('amount');$this->assertSame(0,$r->payments()->count());}
 public function test_frontdesk_cannot_change_property_settings():void {$desk=User::where('role','frontdesk')->firstOrFail();$this->actingAs($desk)->post('/app/settings',[])->assertForbidden();$this->get('/app/channels')->assertForbidden();}
 public function test_housekeeping_cannot_access_guest_or_payment_operations():void {$user=User::where('role','housekeeping')->firstOrFail();$this->actingAs($user)->get('/app/reservations')->assertRedirect('/app/housekeeping');$this->get('/app/housekeeping')->assertOk();$this->post('/app/reservations',[])->assertForbidden();$this->post('/app/reservations/1/payments',[])->assertForbidden();}
 public function test_unassigned_property_is_inaccessible():void {$user=User::where('role','housekeeping')->firstOrFail();$foreign=Property::where('slug','sora-house')->firstOrFail();$this->actingAs($user)->post('/app/property',['property_id'=>$foreign->id])->assertForbidden();$room=$foreign->rooms()->firstOrFail();$this->post('/app/rooms/'.$room->id.'/housekeeping',['housekeeping_status'=>'clean'])->assertNotFound();}
 public function test_unpublished_property_is_hidden():void {$property=Property::where('slug','the-aluna-ubud')->firstOrFail();$property->update(['published'=>false]);$this->get('/')->assertDontSee('The Aluna Ubud');$this->get('/hotels/'.$property->slug)->assertNotFound();$this->post('/hotels/'.$property->slug.'/book',[])->assertNotFound();}
 public function test_feed_has_no_guest_information():void {$room=$this->room();$this->get('/availability/'.$room->calendar_token.'.ics')->assertOk()->assertSee('BEGIN:VCALENDAR')->assertSee('SUMMARY:Unavailable')->assertDontSee('Olivia')->assertDontSee('@example.test');$this->get('/availability/'.str_repeat('x',48).'.ics')->assertNotFound();}
 public function test_successful_checkout_dirties_room_and_releases_remaining_nights():void {$room=$this->room();$r=$room->reservations()->where('status','checked_in')->firstOrFail();app(BookingService::class)->transition($r,'checked_out');$this->assertSame('dirty',$room->fresh()->housekeeping_status);$this->assertSame(0,$room->nights()->count());}
 public function test_out_of_service_room_is_unavailable():void {$room=$this->room();$room->update(['out_of_service'=>true]);$this->expectException(ValidationException::class);app(BookingService::class)->create($room->property,$this->data($room));}
}
